import{_ as a,o as t,c as i,a0 as o}from"./chunks/framework.Cx-5KwGw.js";const m=JSON.parse('{"title":"About Us - Vet Tech Solutions","description":"","frontmatter":{"title":"About Us - Vet Tech Solutions"},"headers":[],"relativePath":"src/about.md","filePath":"src/about.md"}'),n={name:"src/about.md"};function r(l,e,s,c,d,u){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="about-vet-tech-solutions" tabindex="-1">About Vet Tech Solutions <a class="header-anchor" href="#about-vet-tech-solutions" aria-label="Permalink to &quot;About Vet Tech Solutions&quot;">​</a></h1><h2 id="veterans-leading-technical-excellence" tabindex="-1">Veterans Leading Technical Excellence <a class="header-anchor" href="#veterans-leading-technical-excellence" aria-label="Permalink to &quot;Veterans Leading Technical Excellence&quot;">​</a></h2><p><strong>Vet Tech Solutions (VTS Consulting), LLC</strong> is an SBA-verified Service-Disabled Veteran-Owned Small Business (SDVOSB) delivering enterprise IT solutions to federal agencies.</p><h3 id="our-mission" tabindex="-1">Our Mission <a class="header-anchor" href="#our-mission" aria-label="Permalink to &quot;Our Mission&quot;">​</a></h3><p>We combine 20+ years of military-informed discipline with cutting-edge technical expertise to solve complex government technology challenges. Veteran-led agility meets federal compliance standards.</p><h3 id="leadership" tabindex="-1">Leadership <a class="header-anchor" href="#leadership" aria-label="Permalink to &quot;Leadership&quot;">​</a></h3><p><strong>Adam Erickson</strong> – Founder &amp; Principal Consultant<br> U.S. Army veteran with extensive experience in federal IT consulting, cloud architecture, and cybersecurity compliance.</p><h3 id="core-values" tabindex="-1">Core Values <a class="header-anchor" href="#core-values" aria-label="Permalink to &quot;Core Values&quot;">​</a></h3><ul><li><strong>Military Precision</strong>: Reliability, mission-focus, operational excellence</li><li><strong>Clearances</strong>: Active Secret clearance (valid through 2027)</li><li><strong>Compliance</strong>: DCAA, FISMA, NIST 800-171, FedRAMP compliant</li><li><strong>Veteran Commitment</strong>: Dedicated to training and hiring fellow veterans</li></ul><h3 id="naics-codes" tabindex="-1">NAICS Codes <a class="header-anchor" href="#naics-codes" aria-label="Permalink to &quot;NAICS Codes&quot;">​</a></h3><ul><li>541511 - Custom Computer Programming Services</li><li>541512 - Computer Systems Design Services</li><li>541519 - Other Technical Consulting Services</li><li>541513 - Computer Facilities Management</li><li>541518 - Other Computer Related Services</li></ul><h3 id="location" tabindex="-1">Location <a class="header-anchor" href="#location" aria-label="Permalink to &quot;Location&quot;">​</a></h3><p>West Michigan • Remote-First Federal Contracting</p>',13)])])}const p=a(n,[["render",r]]);export{m as __pageData,p as default};
